public function filter_has_access( $has_access, $post_id, $user_id ) {
	$has_access = Cast::to_bool( $has_access );
	$post_id    = Cast::to_int( $post_id );
	$user_id    = Cast::to_int( $user_id );

	// phpcs:ignore WordPress.NamingConventions.PrefixAllGlobals.NonPrefixedHooknameFound -- Intentionally calling WPML's filter.
	if (
		$has_access
		|| ! has_filter( 'wpml_object_id' )
	) {
		return $has_access;
	}

	if ( $post_id <= 0 ) {
		return $has_access;
	}

	// phpcs:ignore WordPress.NamingConventions.PrefixAllGlobals.NonPrefixedHooknameFound -- Intentionally calling WPML's filter.
	$default_lang = Cast::to_string( apply_filters( 'wpml_default_language', '' ) );
	$post_type    = Cast::to_string( get_post_type( $post_id ) );
	// phpcs:ignore WordPress.NamingConventions.PrefixAllGlobals.NonPrefixedHooknameFound -- Intentionally calling WPML's filter.
	$original_id = Cast::to_int( apply_filters( 'wpml_object_id', $post_id, $post_type, true, $default_lang ) );

	if (
		! $original_id
		|| $original_id === $post_id
	) {
		return $has_access;
	}

	return sfwd_lms_has_access_fn( $original_id, $user_id );
}

function ( $access, $post_id, $user_id ) {
	if ( ( is_single() ) && ( ! is_admin() ) ) {
		$lesson_id = learndash_get_lesson_id( $post_id );
		if ( ( true === (bool) $access ) && ( ! empty( $lesson_id ) ) && ( learndash_is_sample( $lesson_id ) ) ) {
			/**
			 * Filters whether to allow access to the sample lesson or not.
			 *
			 * By default a sample lesson is available even to anonymous users. This
			 * filter will override that access. The filer 'learndash_can_access_sample'
			 * is also used themes/ld30/templates/lesson/partials/row.php to control
			 * visibility of the lesson and sub-steps.
			 *
			 * @since 3.2.0
			 *
			 * @param bool $access    Access status true if the user can access $post_id.
			 * @param int  $lesson_id Lesson ID.
			 * @param int  $post_id   Course step the user is trying to access.
			 * @param int  $user_id   User ID.
			 */
			$access = apply_filters(
				'learndash_lesson_sample_access',
				$access,
				(int) $lesson_id,
				learndash_get_course_id(),
				$user_id
			);
		}
	}

	return $access;
},

