function ajax_start_study_session() {
    if (!wp_verify_nonce($_POST['nonce'], 'study_nonce')) {
        wp_send_json_error('Security check failed');
    }

    $user_id = get_current_user_id();
    if (!$user_id) {
        wp_send_json_error('Please log in');
    }

    $deck_id = intval($_POST['deck_id']);
    if (!$deck_id) {
        wp_send_json_error('Invalid deck');
    }

    global $wpdb;
    $progress_table = $wpdb->prefix . 'flashcard_progress';
    $settings_table = $wpdb->prefix . 'flashcard_deck_settings';
    $global_suspensions_table = $wpdb->prefix . 'flashcard_global_suspensions';
    $due = \HebleoStudy\due_sql();$day = \HebleoFollowup\sql($due['now']);

    // Get deck settings
    $settings = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM $settings_table WHERE user_id = %d AND deck_id = %d",
        $user_id, $deck_id
    ));

    if (!$settings) {
        $settings = (object) [
            'new_cards_per_day' => 20,
            'max_reviews_per_day' => 200,
            'card_order' => 'new_first'
        ];
    }

    // Get custom card order for this deck
    $custom_order = get_post_meta($deck_id, '_custom_card_order', true);

    // Build card order clause
    $order_clause = '';
    switch ($settings->card_order) {
        case 'review_first':
            $order_clause = "CASE p.state 
                            WHEN 'learning' THEN 1 
                            WHEN 'relearning' THEN 1
                            WHEN 'review' THEN 2 
                            WHEN 'new' THEN 3 
                            END";
            break;
        case 'mixed':
            $order_clause = "RAND()";
            break;
        default: // new_first
            $order_clause = "CASE p.state 
                            WHEN 'learning' THEN 1 
                            WHEN 'relearning' THEN 1
                            WHEN 'new' THEN 2 
                            WHEN 'review' THEN 3 
                            END";
            break;
    }

    // Get new cards
    $new_cards = $wpdb->get_results($wpdb->prepare(
        "SELECT p.* FROM $progress_table p {$day['join']}
         WHERE {$day['where']} AND p.user_id = %d AND p.deck_id = %d AND p.state = 'new' AND p.suspended = 0
         AND NOT EXISTS (SELECT 1 FROM $global_suspensions_table gs WHERE gs.note_id = p.note_id AND gs.template_id = p.template_id)
         ORDER BY {$order_clause}, p.created_at ASC
         LIMIT %d",
        $user_id, $deck_id, $settings->new_cards_per_day
    ));

    // Apply custom order to new cards if exists
    if (is_array($custom_order) && !empty($custom_order) && !empty($new_cards)) {
        $ordered_new_cards = [];
        foreach ($custom_order as $card_key) {
            list($note_id, $template_id) = explode('_', $card_key);
            foreach ($new_cards as $card) {
                if ($card->note_id == $note_id && $card->template_id == $template_id) {
                    $ordered_new_cards[] = $card;
                    break;
                }
            }
        }
        // Add any remaining cards not in custom order
        foreach ($new_cards as $card) {
            $key = $card->note_id . '_' . $card->template_id;
            if (!in_array($key, $custom_order)) {
                $ordered_new_cards[] = $card;
            }
        }
        $new_cards = array_slice($ordered_new_cards, 0, $settings->new_cards_per_day);
    }

    // Get review cards (reviews don't use custom order)
    $review_cards = $wpdb->get_results($wpdb->prepare(
        "SELECT p.* FROM $progress_table p {$due['join']}
         WHERE p.user_id = %d AND p.deck_id = %d 
         AND p.state IN ('learning', 'relearning', 'review') 
         AND {$due['where']} AND p.suspended = 0
         AND NOT EXISTS (SELECT 1 FROM $global_suspensions_table gs WHERE gs.note_id = p.note_id AND gs.template_id = p.template_id)
         ORDER BY {$order_clause}, {$due['epoch']} ASC, p.id ASC
         LIMIT %d",
        $user_id, $deck_id, $settings->max_reviews_per_day
    ));

    $all_cards = array_merge($new_cards, $review_cards);

    if ($settings->card_order === 'mixed') {
        shuffle($all_cards);
    }

    if (empty($all_cards)) {
        wp_send_json_error('No cards due');
    }

    $cards = [];
    foreach ($all_cards as $card_progress) {
        $card_data = prepare_study_card($card_progress);
        if ($card_data) {
            $cards[] = $card_data;
        }
    }

    wp_send_json_success(['cards' => $cards]);
}

