function ajax_get_study_decks() {
    if (!wp_verify_nonce($_POST['nonce'], 'study_nonce')) {
        wp_send_json_error('Security check failed');
    }

    $user_id = get_current_user_id();
    if (!$user_id) {
        wp_send_json_error('Please log in to study');
    }

    global $wpdb;

    $decks = get_posts([
        'post_type' => 'decks',
        'post_status' => 'publish',
        'numberposts' => -1,
        'orderby' => 'title',
        'order' => 'ASC'
    ]);

    $deck_data = [];
    $deck_settings = [];
    $progress_table = $wpdb->prefix . 'flashcard_progress';
    $global_suspensions_table = $wpdb->prefix . 'flashcard_global_suspensions';
    $settings_table = $wpdb->prefix . 'flashcard_deck_settings';

    foreach ($decks as $deck) {
        // Initialize progress for this deck
        initialize_deck_progress($user_id, $deck->ID);

        $due = \HebleoStudy\due_sql();$day = \HebleoFollowup\sql($due['now']);

        $new_cards = $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM $progress_table p {$day['join']} 
             WHERE {$day['where']} AND p.user_id = %d AND p.deck_id = %d AND p.state = 'new' AND p.suspended = 0
         AND NOT EXISTS (SELECT 1 FROM $global_suspensions_table gs WHERE gs.note_id = p.note_id AND gs.template_id = p.template_id)
             AND NOT EXISTS (SELECT 1 FROM $global_suspensions_table gs WHERE gs.note_id = p.note_id AND gs.template_id = p.template_id)",
            $user_id, $deck->ID
        ));

        $learning_cards = $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM $progress_table p {$due['join']} 
             WHERE p.user_id = %d AND p.deck_id = %d AND p.state IN ('learning', 'relearning') 
             AND {$due['where']} AND p.suspended = 0
             AND NOT EXISTS (SELECT 1 FROM $global_suspensions_table gs WHERE gs.note_id = p.note_id AND gs.template_id = p.template_id)",
            $user_id, $deck->ID
        ));

        $review_cards = $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM $progress_table p {$due['join']} 
             WHERE p.user_id = %d AND p.deck_id = %d AND p.state = 'review' 
             AND {$due['where']} AND p.suspended = 0
             AND NOT EXISTS (SELECT 1 FROM $global_suspensions_table gs WHERE gs.note_id = p.note_id AND gs.template_id = p.template_id)",
            $user_id, $deck->ID
        ));

        // Get deck settings
        $settings = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $settings_table WHERE user_id = %d AND deck_id = %d",
            $user_id, $deck->ID
        ));

        if (!$settings) {
            // Create default settings
            $wpdb->insert($settings_table, [
                'user_id' => $user_id,
                'deck_id' => $deck->ID,
                'new_cards_per_day' => 20,
                'max_reviews_per_day' => 200,
                'card_order' => 'new_first'
            ]);
            $settings = (object) [
                'new_cards_per_day' => 20,
                'max_reviews_per_day' => 200,
                'card_order' => 'new_first',
                'autoplay_audio' => 1
            ];
        }

        $deck_data[] = [
            'id' => $deck->ID,
            'title' => $deck->post_title,
            'new_cards' => intval($new_cards),
            'learning_cards' => intval($learning_cards),
            'review_cards' => intval($review_cards)
        ];

        $deck_settings[$deck->ID] = [
            'new_cards_per_day' => intval($settings->new_cards_per_day),
            'max_reviews_per_day' => intval($settings->max_reviews_per_day),
            'card_order' => $settings->card_order,
            'autoplay_audio' => intval($settings->autoplay_audio)
        ];
    }

    wp_send_json_success([
        'decks' => $deck_data,
        'settings' => $deck_settings
    ]);
}
